import type { Readable, Writable } from 'node:stream';
import { pipeline } from 'node:stream/promises';
export interface ExportOptions { signal?: AbortSignal; }
export async function exportRecords(source: Readable, destination: Writable, options: ExportOptions = {}): Promise<void> {
  await pipeline(source, destination, { signal: options.signal });
}
